// db.ts
import type { BSIDataCatalogue, BSIDataSystem } from "./bs_types";
import type { Table } from "dexie";
import type { GameSystemRow, GithubGameSystemRow } from "~/assets/shared/types/system_types";

import Dexie from "dexie";

export class MySubClassedDexie extends Dexie {
  catalogues!: Table<{ id: string; content: BSIDataCatalogue; path?: string }>;
  systems!: Table<{ id: string; content: BSIDataSystem; path?: string, handle?: FileSystemDirectoryHandle }>;
  systemrows!: Table<GameSystemRow | GithubGameSystemRow>;
  handles!: Table<{ id: string; handle: FileSystemDirectoryHandle | FileSystemFileHandle }>;

  constructor() {
    super("nr-editor");
    this.version(6).stores({
      catalogues: "id, content.catalogue.id, content.catalogue.gameSystemId",
      systems: "id",
      systemrows: "id",
    });
    this.version(7).stores({
      handles: "id",
    });
  }
}

export const db = new MySubClassedDexie();
