export const arrayKeys = new Set([...Object.keys(entries).filter((s) => s.endsWith("s"))]);
export type ArrayKey = Extract<keyof typeof entries, `${string}s`>;
// Sound for any whiteList that is a subset of arrayKeys, which is all of them today.
export function isArrayKey(key: string, whiteList: ReadonlySet<string> = arrayKeys): key is ArrayKey {
  return whiteList.has(key);
}
/** Only 11 of the ArrayKeys are declared on Base itself; the rest live on subclasses. */
type ChildContainer = { readonly [K in ArrayKey]?: Base | Base[] };

/** Returned from a walkChildren callback to stop the walk and hand that child back. */
export const STOP = Symbol("walkChildren.stop");

export interface WalkOptions {
  whiteList?: ReadonlySet<string>;
  maxDepth?: number;
  /** Also descend into each visited child's link target. */
  includeTargets?: boolean;
}

/**
 * Breadth-first walk over whitelisted child objects, shared by every walker below.
 * The callback returns `false` to skip descending into that child, `STOP` to end
 * the walk (walkChildren then returns that child), and anything else to descend.
 */
export function walkChildren(
  root: Base,
  callbackfn: (child: Base, parent: Base, key: ArrayKey) => unknown,
  { whiteList = arrayKeys, maxDepth, includeTargets }: WalkOptions = {},
): Base | undefined {
  let stack: Base[] = [root];
  let next: Base[] = [];
  let depth = 0;

  while (stack.length) {
    while (stack.length) {
      const current = stack.pop()!;
      // The only cast in the traversal: ArrayKeys are spread across Base and its subclasses.
      const container = current as unknown as ChildContainer;
      for (const key in current) {
        if (!isArrayKey(key, whiteList)) continue;
        const value = container[key];
        if (!isObject(value)) continue;
        if (Array.isArray(value)) {
          if (!value.length || !isObject(value[0])) continue;
          for (let i = 0; i < value.length; i++) {
            const child = value[i];
            const res = callbackfn(child, current, key);
            if (res === STOP) return child;
            if (res === false) continue;
            next.push(child);
            if (includeTargets && child.target) next.push(child.target);
          }
        } else {
          const res = callbackfn(value, current, key);
          if (res === STOP) return value;
          if (res === false) continue;
          next.push(value);
          if (includeTargets && value.target) next.push(value.target);
        }
      }
    }
    stack = next;
    next = [];
    depth++;
    if (maxDepth && depth >= maxDepth) break;
  }
}
export function getDataObject(data: BSIData | Catalogue): BSIGameSystem | BSICatalogue {
  if ((data as Catalogue).isCatalogue && (data as Catalogue).isCatalogue()) {
    return data as BSICatalogue;
  }
  if ((data as BSIData).gameSystem) return (data as BSIData).gameSystem!;
  if ((data as BSIData).catalogue) return (data as BSIData).catalogue!;
  throw Error("getDataObject data argument is not a valid system or catalogue");
}

// BSIData declares gameSystem and catalogue both optional, so `if (data.gameSystem)` narrows the
// property but leaves the object typed BSIData; these narrow the object the call site passes on.
export function isDataSystem(data: BSIData): data is BSIData & BSIDataSystem {
  return data.gameSystem !== undefined;
}

export function isDataCatalogue(data: BSIData): data is BSIData & BSIDataCatalogue {
  return data.catalogue !== undefined;
}

export function getDataDbId(data: BSIData | Catalogue): string {
  if ((data as Catalogue).isCatalogue && (data as Catalogue).isCatalogue()) {
    if (data.id && data.gameSystemId) {
      return `${data.gameSystemId}-${data.id}`;
    }
    if (data.id) {
      return `${data.id}`;
    }
  }
  if (data.catalogue) {
    return `${data.catalogue.gameSystemId}-${data.catalogue.id}`;
  }
  if (data.gameSystem) {
    return data.gameSystem.id;
  }
  throw Error("getDataId data argument is not a valid system or catalogue");
}
