import { Parser } from "expr-eval";
export class FormatRule extends Base implements IFormatRule {
  declare match: string;
  declare replace: string;
  declare type: "regex";

  apply(value: string): string {
    // Community-system data feeds numeric characteristic values into format rules (NR-43).
    if (typeof value !== "string") value = String(value ?? "");
    const replace = this.replace ?? "";
    const match = this.match ?? "([\\s\\S]*)";
    if (replace.includes("|")) {
      return value.replace(new RegExp(match, "g"), (match, ...args) => {
        return replace.replace(/\$(&|\d+|{\w+})(?:\|([^$]+))?/g, (_, ref: string, filters?: string) => {
          const group = this.getRegexGroup(match, args, ref);
          return this.applyFormattingActions(filters, group);
        });
      });
    }
    return value.replace(new RegExp(match), replace);
  }
  getRegexGroup(match: string, args: unknown[], ref: string): string {
    if (ref === "&") return match;

    const numMatch = ref.match(/^\d+$/);
    if (numMatch) {
      const index = parseInt(ref);
      return (args.slice(0, -2)[index - 1] ?? "") as string;
    }

    const namedMatch = ref.match(/^{(\w+)}$/);
    if (namedMatch) {
      const groupName = namedMatch[1];
      const groupsObject = args[args.length - 1];
      if (groupsObject && typeof groupsObject === "object" && groupName in groupsObject) {
        return (groupsObject as Record<string, string>)[groupName] ?? "";
      }
    }

    const bracedNumMatch = ref.match(/^{(\d+)}$/);
    if (bracedNumMatch) {
      const index = parseInt(bracedNumMatch[1]);
      return (args.slice(0, -2)[index] ?? "") as string;
    }

    return "";
  }

  applyFormattingActions(filters: string | undefined, val: string): string {
    if (filters) {
      for (const filter of filters.split("|")) {
        const f = filter.trim();
        if (f === "eval") {
          try {
            const r = Parser.evaluate(val);
            val = typeof r === "number" && !isNaN(r) ? String(r) : val;
          } catch {
            console.error(`Error evaluating expression: ${val}`);
          }
        } else if (f === "sign") {
          val = Number(val).toLocaleString("en-US", { signDisplay: "always" });
        } else if (f === "abs") {
          const n = parseFloat(val);
          if (!isNaN(n)) val = String(Math.abs(n));
        }
      }
    }
    return val;
  }
}

