export function getStaticFilters(source: Base): string[] {
  const ids = ["any", source.id];
  if (source.isLink()) ids.push(source.targetId);

  if (source.isForce()) ids.push("force");
  else if (source.isEntry()) ids.push("entry");
  else if (source.isGroup()) ids.push("group");
  else if (source.isCategory()) ids.push("category");
  else if (source.isRoster()) ids.push("roster");

  const type = source.getType();
  if (type) ids.push(type);
  // Alias so association filters can match either type with a single childId
  if (type === "model" || type === "unit") ids.push("model-or-unit");
  return ids;
}

export function getIds(source: Base): string[] {
  return source.isLink() ? [source.id, source.targetId] : [source.id];
}
export function* getAllInfoGroups(group: Base): Iterable<InfoGroup> {
  yield group as InfoGroup;
  for (const grp of group.infoGroups || []) {
    yield* getAllInfoGroups(grp);
  }
  for (const link of group.infoLinks || []) {
    if (link.type === "infoGroup") yield* getAllInfoGroups(link.target as InfoGroup);
  }
}
export function iterateModifierGroupsRecursive(groups?: Iterable<ModifierGroup>): Iterable<ModifierGroup>;
export function iterateModifierGroupsRecursive(groups?: Iterable<BSIModifierGroup>): Iterable<BSIModifierGroup>;
export function* iterateModifierGroupsRecursive(groups?: Iterable<BSIModifierGroup>): Iterable<BSIModifierGroup> {
  if (groups) {
    for (const group of groups) {
      yield group;
      yield* iterateModifierGroupsRecursive(group.modifierGroups);
    }
  }
}
// True if any modifier on this holder is relative, including ones nested in modifierGroups.
function hasRelativeModifierRecursive(holder: Base): boolean {
  for (const modifier of holder.modifiers || []) {
    if (isRelativeModifier(modifier)) return true;
  }
  for (const group of iterateModifierGroupsRecursive(holder.modifierGroups)) {
    for (const modifier of group.modifiers || []) {
      if (isRelativeModifier(modifier)) return true;
    }
  }
  return false;
}
// Recursively checks a node's info (profiles, rules, infoGroups, infoLinks and
// link targets) for any relative modifier. Short-circuits on the first hit.
export function hasRelativeModifierOnInfoRecursive(node: Base): boolean {
  for (const profile of node.profiles || []) {
    if (hasRelativeModifierRecursive(profile)) return true;
  }
  for (const rule of node.rules || []) {
    if (hasRelativeModifierRecursive(rule)) return true;
  }
  for (const group of node.infoGroups || []) {
    if (hasRelativeModifierRecursive(group) || hasRelativeModifierOnInfoRecursive(group)) return true;
  }
  for (const link of node.infoLinks || []) {
    if (hasRelativeModifierRecursive(link)) return true;
    const target = link.target;
    if (target && (hasRelativeModifierRecursive(target) || hasRelativeModifierOnInfoRecursive(target))) return true;
  }
  return false;
}

