export function rootToJson(data: Catalogue | BSICatalogue | BSIGameSystem | Record<string, unknown>, fixRoot = false): string {
  const root: any = {
    catalogue: undefined,
    gameSystem: undefined,
  };
  const copy = { ...data }; // ensure there is no recursivity by making sure only this copy is put in the json
  if (!data.gameSystemId) {
    root.gameSystem = copy;
    root.gameSystem.type = "gameSystem";
    delete root.catalogue;
  } else {
    root.catalogue = copy;
    root.catalogue.type = "catalogue";
    delete root.gameSystem;
  }

  const obj = fixRoot ? getDataObject(root) : root;
  // The replacer decides WHAT is written (whitelisted keys, no empty arrays, exactly-constraints
  // split); compactStringify decides how it is laid out -- name/id first, arrays last, small
  // objects on one line -- so a git diff of a catalogue is readable. Both the editor's saves and
  // the MCP tool results go through the same formatter.
  const filtered = JSON.stringify(obj, (k, v) => {
    if (Array.isArray(v) && v.length === 0) return undefined;
    if (v === copy || goodJsonKeys.has(k) || isFinite(Number(k))) {
      if (isObject(v)) {
        return splitExactlyConstraints(splitExactlyConstraintsModifiers(v));
      }
      return v;
    }
    return undefined;
  });
  // Trailing newline: without it every commit ends in git's "No newline at end of file" marker.
  return compactStringify(JSON.parse(filtered), 2) + "\n";
}
export function entryToJson(data: Base | Record<string, unknown>, extraFields?: Set<string>): string {
  const stringed = JSON.stringify(data, function (k, v) {
    if (Array.isArray(v) && v.length === 0) return undefined;
    if (goodJsonKeys.has(k) || isFinite(Number(k)) || extraFields?.has(k)) return v;
    return undefined;
  });
  return stringed;
}

interface EntriesToJsonOptions {
  formatted?: boolean;
  forceArray?: boolean; // default is true
}
export function entriesToJson(data: Array<Base | Record<string, unknown>> | Base | Record<string, unknown>, extraFields?: Set<string>, options?: EntriesToJsonOptions): string {
  const takeOutOfArray = options?.forceArray === false;
  data = Array.isArray(data) && data?.length === 1 && takeOutOfArray ? data[0] : data;
  const stringed = JSON.stringify(
    data,
    function (k, v) {
      if (goodJsonKeys.has(k) || isFinite(Number(k)) || extraFields?.has(k)) return v;
      return undefined;
    },
    options?.formatted === true ? 2 : undefined,
  );
  return stringed;
}

// Discards the callback's return value on purpose: callers pass concise arrows that return
// booleans (updateLink), which walkChildren would otherwise read as a prune signal.
export function forEachObjectWhitelist2<T extends Base>(current: Base, callbackfn: (value: T, parent: T) => unknown, whiteList = arrayKeys) {
  walkChildren(
    current,
    (child, parent) => {
      callbackfn(child as T, parent as T);
    },
    { whiteList },
  );
}

export function convertRuleToProfile<S>(rule: (BSIDescription & BSINamed & BSIHidden) & { source?: S }): BSIProfile & { source?: S } {
  return {
    characteristics: [
      {
        name: "Description",
        typeId: "description",
        kind: "longText",
        $text: Array.isArray(rule.description) ? rule.description[0] : rule.description,
      },
    ],
    attributes: [],
    id: rule.id,
    name: rule.name,
    hidden: rule.hidden ?? false,
    typeId: "rules",
    typeName: "Rules",
    source: rule.source,
  };
}
export function convertCategoryToProfile<S>(rule: (BSIDescription & BSINamed & BSIHidden) & { source?: S }): BSIProfile & { source?: S } {
  return {
    characteristics: [
      {
        name: "Description",
        typeId: "description",
        kind: "longText",
        $text: Array.isArray(rule.description) ? rule.description[0] : rule.description,
      },
    ],
    attributes: [],
    id: rule.id,
    name: rule.name,
    hidden: rule.hidden ?? false,
    typeId: "(description)",
    typeName: "Description",
    source: rule.source,
  };
}

export interface AffectsQuery {
  self?: boolean;
  entries?: boolean;
  forces?: boolean;
  group?: boolean;
  associations?: boolean;
  recursive?: boolean;
  filterBy?: string;
  affectsWhat?: string;
}
export function readable_affects_query(fields: AffectsQuery, idToString: (id: string) => string) {
  const result = [];
  if (fields.self && (fields.entries || fields.forces)) result.push("self");
  if (fields.entries) result.push("entries");
  if (fields.forces) result.push("forces");
  if (fields.group) result.push("group");
  if (fields.recursive) result.push("recursive");
  if (fields.filterBy && fields.filterBy !== "any") result.push(idToString(fields.filterBy));
  if (fields.affectsWhat && fields.affectsWhat !== "entries") result.push(idToString(fields.affectsWhat));
  const combined = result.join(".");
  return combined;
}
export function construct_affects_query(fields: AffectsQuery) {
  const result = [];
  if (fields.self && (fields.entries || fields.forces)) result.push("self");
  if (fields.entries) result.push("entries");
  if (fields.forces) result.push("forces");
  if (fields.group) result.push("group");
  if (fields.recursive) result.push("recursive");
  if (fields.filterBy && fields.filterBy !== "any") result.push(fields.filterBy);
  if (fields.affectsWhat && fields.affectsWhat !== "entries") result.push(fields.affectsWhat);
  const combined = result.join(".");
  return combined;
}
export function deconstruct_affects_query(query?: string): AffectsQuery {
  const selectors = ["profiles", "constraints", "costs", "rules", "categories"];
  const filterBy = [];
  const flags = {
    self: false,
    entries: false,
    forces: false,
    recursive: false,
    associations: false,
    group: false,
  } as Record<string, boolean>;

  const split = (query || "").replace("childs", "entries").split(".");
  let affectsWhat = "entries";

  for (let i = 0; i < split.length; i++) {
    const cur = split[i];
    if (selectors.includes(cur)) {
      affectsWhat = split.slice(i).join(".");
      break;
    }
    if (cur in flags) {
      flags[cur] = true;
      continue;
    }
    filterBy.push(cur);
  }

  if (!flags.entries && !flags.forces) {
    flags.self = true;
  }

  return {
    ...flags,
    filterBy: filterBy.length ? filterBy.join(".") : "any",
    affectsWhat: flags.associations ? `associations.${affectsWhat}` : affectsWhat,
  };
}
