/**
 * Called after a node has been given its class prototype, with the key it was found under.
 *
 * The editor grafts a second, per-parentKey prototype on top to carry `parentKey` and
 * `editorTypeName`. Nothing else wants it, and it used to be wired in right here -- which
 * dragged the whole editor module into every build of the roster app that shares this file.
 * Registered by assets/editor/catalogue_editor.ts; unset everywhere else, so the call costs
 * one undefined check.
 */
let afterSetPrototype: ((obj: object, key: string) => void) | undefined;
export function onSetPrototype(fn: typeof afterSetPrototype): void {
  afterSetPrototype = fn;
}

export const protoMap = {
  "*": Base.prototype,
  // "*": Base.prototype,
  catalogue: Catalogue.prototype,
  catalogueLinks: CatalogueLink.prototype,
  gameSystem: GameSystem.prototype,

  sharedForceEntries: Force.prototype,
  forceEntries: Force.prototype,
  forces: Force.prototype,
  forceEntry: Force.prototype,
  force: Force.prototype,
  forceEntryLinks: ForceEntryLink.prototype,

  categoryEntries: Category.prototype,
  categoryEntry: Category.prototype,
  category: Category.prototype,
  categories: Category.prototype,

  link: Link.prototype,
  infoLinks: InfoLink.prototype,
  categoryLinks: CategoryLink.prototype,

  entry: Entry.prototype,
  selectionEntries: Entry.prototype,
  entryLinks: Link.prototype,
  sharedSelectionEntries: Entry.prototype,

  group: Group.prototype,
  selectionEntryGroups: Group.prototype,
  sharedSelectionEntryGroups: Group.prototype,

  sharedRules: Rule.prototype,
  rules: Rule.prototype,
  rule: Rule.prototype,

  profileTypes: ProfileType.prototype,
  sharedProfiles: Profile.prototype,
  profiles: Profile.prototype,
  profile: Profile.prototype,
  characteristics: Characteristic.prototype,
  characteristic: Characteristic.prototype,
  characteristicTypes: CharacteristicType.prototype,
  characteristicType: CharacteristicType.prototype,
  formatRules: FormatRule.prototype,

  sharedInfoGroups: InfoGroup.prototype,
  infoGroups: InfoGroup.prototype,
  infoGroup: InfoGroup.prototype,

  publications: Publication.prototype,
  publication: Publication.prototype,

  repeats: Repeat.prototype,
  conditions: Condition.prototype,
  constraints: Constraint.prototype,
  modifiers: Modifier.prototype,
  modifierGroups: ModifierGroup.prototype,
  conditionGroups: ConditionGroup.prototype,

  sharedAssociations: Association.prototype,
  associations: Association.prototype,
  associationLinks: AssociationLink.prototype,
};
export const protoMapValues = Object.values(protoMap);
export type ProtoMap = typeof protoMap;
export function getPrototypeFromKey(key: string) {
  if (key in protoMap) {
    return protoMap[key as keyof typeof protoMap]!;
  } else {
    return protoMap["*"];
  }
}

export function setPrototype<Key extends string>(obj: object, key: Key): Key extends keyof ProtoMap ? ProtoMap[Key] : ProtoMap[keyof ProtoMap] {
  const newProto = getPrototypeFromKey(key);
  if (newProto) {
    Object.setPrototypeOf(obj, newProto);
    const hooks = obj as { post_init?: () => void };
    if (hooks.post_init) hooks.post_init();
    afterSetPrototype?.(obj, key);
  }
  return obj as ReturnType<typeof setPrototype<Key>>;
}

export function setPrototypeRecursive(obj: any): void {
  const stack = [obj];
  while (stack.length) {
    const current = stack.pop();
    for (const key of Object.keys(current)) {
      const value = current[key];

      if (isObject(value)) {
        // If Array: set prototypes on each object inside it. Every element is tested rather than
        // assuming the array is homogeneous from its first: a hole, a null or a non-object at index
        // 0 used to skip every real node behind it, leaving them without prototypes.
        if (Array.isArray(value)) {
          for (let i = value.length; i--; ) {
            const cur = value[i];
            if (isObject(cur) && isDefaultObject(cur)) {
              setPrototype(cur, key);
              stack.push(cur);
            }
          }
        }
        //  If Object: Set Prototype on object
        else {
          if (isDefaultObject(value)) {
            setPrototype(value, key);
            stack.push(value);
          }
        }
      }
    }
  }

  // return result;
}
