import type { Catalogue } from "./bs_main_catalogue";
import type { BSCatalogueManager } from "./bs_system";
import type { BSIData } from "./bs_types";
import type { BooksDate } from "./bs_versioning";

import { setPrototypeRecursive, setPrototype } from "./bs_main_types";

export interface loadDataOptions {
  deleteBadLinks: boolean;
}
export async function loadData(
  system: BSCatalogueManager,
  data: BSIData,
  booksDate?: BooksDate,
  options?: loadDataOptions,
  /** Catalogues above this one whose own load has not finished yet. See the cycle check below. */
  loading: Catalogue[] = []
): Promise<Catalogue> {
  if (!data.catalogue && !data.gameSystem) {
    throw Error(`invalid loadBsData argument: no .catalogue or .gameSystem in data`);
  }

  const key = data.catalogue ? "catalogue" : "gameSystem";
  const isSystem = key === "gameSystem";
  const isCatalogue = key === "catalogue";
  const obj = data[key]!;
  const asCatalogue = obj as unknown as Catalogue;
  if (asCatalogue.loaded || asCatalogue.loaded_editor) {
    return asCatalogue;
  }
  // Prevent infinite loops by checking if prototype is already set
  setPrototypeRecursive(obj);
  const content = setPrototype(obj, key);
  // Catalogue.manager is declared as `isEditor extends true ? GameSystemFiles : BSCatalogueManager`,
  // so in the editor build it is the narrower type while this loader is handed the base one.
  // The editor only ever passes a GameSystemFiles; the cast is that guarantee, stated once.
  content.manager = system as typeof content.manager;
  const chain = [...loading, content];

  // Resolve gameSystem
  if (isCatalogue) {
    const link = { targetId: content.gameSystemId! };
    const alreadyLoadedGameSystem = system.getLoadedCatalogue(link, booksDate);
    if (alreadyLoadedGameSystem) {
      content.gameSystem = alreadyLoadedGameSystem;
    } //
    else {
      const data = await system.getData(link, booksDate);
      const loadedGameSystem = system.getLoadedCatalogue(link, booksDate);
      if (loadedGameSystem) {
        content.gameSystem = loadedGameSystem;
      } //
      else {
        content.gameSystem = await loadData(system, data, booksDate, options, chain);
      }
    }
  }

  // Resolve catalogue Links
  const promises = [];
  for (const link of content?.catalogueLinks || []) {
    if (!link.targetId) {
      console.warn(`invalid link: no targetId in link: ${link}, found in ${obj.name}`);
      continue;
    }

    /**
     * A link back to a catalogue still loading above this one.
     *
     * Nothing is registered with the manager until its own links have resolved, so following
     * such a link loads that catalogue again, which follows the link again, forever -- the
     * editor hangs partway through the file list and eventually dies. Point the link at the
     * in-progress object instead: it is the very object that is being filled in, so by the
     * time anything reads through it, it is complete.
     *
     * The data is still wrong -- what each side of a loop imports depends on which file was
     * opened first -- so the loop is also reported per link by the catalogue-link-cycle
     * diagnostic. This console line is for the case where the load itself is what someone is
     * staring at.
     */
    const cyclic = chain.find((o) => o.id === link.targetId);
    if (cyclic) {
      link.target = cyclic;
      console.error(
        `Recursive catalogue link: ${[...chain, cyclic].map((o) => o.name?.trim() || o.id).join(" -> ")}`
      );
      continue;
    }
    const alreadyLoadedCatalogue = system.getLoadedCatalogue(link, booksDate);
    if (alreadyLoadedCatalogue) {
      link.target = alreadyLoadedCatalogue;
      continue;
    } //

    const promise = system.getData(link, booksDate).then((data) => {
      const loadedCatalogue = system.getLoadedCatalogue(link, booksDate);
      if (loadedCatalogue) {
        link.target = loadedCatalogue;
        return;
      }
      return loadData(system, data, booksDate, options, chain).then((data) => (link.target = data));
    });
    promises.push(promise);
  }
  await Promise.all(promises);

  // Add loaded catalogue to Manager
  if (isSystem) {
    system.addLoadedSystem(content);
  }
  if (isCatalogue) {
    system.addLoadedCatalogue(content);
  }

  return content;
}
