import { forEachPairRecursive, removePrefix } from "./bs_helpers";
import { arrayKeys, Base, getDataObject } from "./bs_main";

export type Translated<T> = {
    [K in keyof T as `original_${string & K}`]: T[K];
};

// Fields the engine matches on (type === "model", scope, field...); translating a value here breaks conditions.
// Mirrored as UNTRANSLATABLE_KEYS in nr-translation/assets/ts/bs_translate.ts so the tool never offers them.
export const UNTRANSLATABLE_KEYS = new Set<string>(["id", "type", "field", "scope", "affects", "kind"]);

export function isTranslatableKey(key: string): boolean {
    return !UNTRANSLATABLE_KEYS.has(key) && !key.includes("Id");
}

export function translate(json: Record<string, any>, translations: Record<string, string>) {
    forEachPairRecursive(
        getDataObject(json),
        (value, key, obj) => {
            if (typeof value !== "string") return;
            if (!isTranslatableKey(key)) return;
            if (value in translations) {
                obj[key] = translations[value];
                obj[`original_${key}`] = value;
            }
        },
        (obj, key) => arrayKeys.has(key),
    );
}

export function untranslate(json: Record<string, any>) {
    forEachPairRecursive(
        getDataObject(json),
        (value, key, obj) => {
            if (key.startsWith("original_")) {
                const actualKey = removePrefix(key, "original_");
                obj[actualKey] = value;
                delete obj[key];
            }
        },
        (obj, key) => {
            if (!arrayKeys.has(key)) return false;
            if (!(obj instanceof Base)) return false;
            return true;
        },
    );
}

export function getOriginalText<T extends Record<string, any>, KT extends string>(obj: T, key: KT): T[KT] {
    // The original_-prefixed twin holds the same type as the key it shadows; TS cannot express
    // that relation between two independent index accesses.
    return (obj[`original_${key}`] ?? obj[key]) as T[KT]
}