

export class InfoIndex<T = any> {
    // Null-prototype: names like "constructor" or "toString" are real words in game text, and on
    // a plain object they walk into Object.prototype members instead of the trie.
    index = Object.create(null) as Record<string, any>;
    // Hand-rolled tokenizer: /(\w+|\s|\W)/g overflowed Firefox's regex stack on a huge single token (NR-10E)
    words(str: string): string[] {
        const s = `${str}`.trim();
        const out: string[] = [];
        let start = -1;
        for (let i = 0; i <= s.length; i++) {
            const c = i < s.length ? s.charCodeAt(i) : -1;
            const isWord = (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c === 95;
            if (isWord) {
                if (start < 0) start = i;
                continue;
            }
            if (start >= 0) {
                out.push(s.slice(start, i));
                start = -1;
            }
            if (c >= 0) out.push(s[i]);
        }
        return out.length ? out : [s];
    }
    /**
     * Deliberately case-sensitive for ALL-CAPS words: a keyword is usually uppercase ("AP",
     * "FLY") and the same letters can be an ordinary word in a sentence, so only words that
     * already contain lowercase are folded.
     */
    clean(word: string): string {
        return word.match(/[a-z]/) ? word.toLowerCase() : word;
    }
    add(text: string, value: T) {
        if (typeof text !== "string" || !text.match(/(?=.*[a-zA-Z0-9].*[a-zA-Z0-9])/)) {
            return;
        }
        this.addToIndex(this.index, value, this.words(text));
    }
    private addToIndex(out: Record<string, any>, obj: any, words: string[]) {
        for (const raw of words) {
            const word = this.clean(raw);
            if (word === " ") continue;
            out = out[word] ??= Object.create(null);
        }
        (out.$ ??= []).push(obj);
    }
    match(text: string | number): { match?: T[], text?: string }[] {
        if (typeof text !== "string" || !text.match(/(?=.*[a-zA-Z0-9].*[a-zA-Z0-9])/)) {
            return [{ text: text as string }]
        }
        const words = this.words(text)
        const clean = words.map(this.clean, this)



        const result = []
        let currentText = []
        for (let i = 0; i < clean.length; i++) {
            let cur = this.index;
            let latest = 0
            let latestVal;
            if (isMultilineCodeBlockStart(clean, i)) {
                const end = findMultilineCodeBlockEnd(i, clean)
                if (end !== -1) {
                    const foundText = words.slice(i, end + 1).join("")
                    currentText.push(foundText)
                    i = end;
                }
                continue;
            } else if (isCodeBlockStart(clean, i)) {
                const end = findCodeBlockEnd(i, clean)
                if (end !== -1) {
                    const foundText = words.slice(i, end + 1).join("")
                    currentText.push(foundText)
                    i = end;
                }
                continue;
            }


            if (clean[i] !== " ") {
                for (let j = i; j < clean.length; j++) {
                    const word = clean[j]
                    if (word === " ") continue;
                    cur = cur[word]
                    if (cur) {
                        if (cur.$) {
                            latest = 1 + (j - i)
                            latestVal = cur.$
                        }
                    } else {
                        break;
                    }
                }
            }
            if (latest) {
                if (currentText.length) {
                    result.push({ text: currentText.join("") })
                    currentText = []
                }
                result.push({ match: latestVal, text: words.slice(i, i + latest).join("") });
                i += latest - 1
            } else {
                currentText.push(words[i])
            }
        }
        if (currentText.length) {
            result.push({ text: currentText.join("") })
        }
        return result
    }

}
/** Index of the closing fence's last backtick, or -1. (Tested `clean[i]` before -- the OPENING fence -- so every block "closed" 4 tokens in.) */
function findMultilineCodeBlockEnd(i: number, clean: string[]) {
    for (let j = i + 3; j < clean.length; j++) {
        if (clean[j] === "`" && clean[j + 1] === "`" && clean[j + 2] === "`") {
            return j + 2;
        }
    }
    return -1
}
/** Index of the closing backtick, or of the newline that cuts the span short, or -1. */
function findCodeBlockEnd(i: number, clean: string[]) {
    for (let j = i + 1; j < clean.length; j++) {
        if (clean[j] === "`" || clean[j] === "\n") {
            return j;
        }
    }
    return -1
}
function isCodeBlockStart(clean: string[], i: number) {
    return clean[i] === "`"
}

function isMultilineCodeBlockStart(clean: string[], i: number) {
    return clean[i] === "`" && clean[i + 1] === "`" && clean[i + 2] === "`"
}