/**
 * JSON layout for files people diff and tools people read.
 *
 * JSON.stringify(x, null, 2) puts every key of every object on its own line, in insertion
 * order. For catalogue data that meant a profile's `characteristics` array came before its
 * `name`, a condition took seven lines, and a git hunk started with screens of context before
 * the field that said what was being changed. This writes:
 *
 *   - scalars before arrays/objects, so an object opens with what identifies it
 *   - `name` and `id` first, then the remaining scalars alphabetically, then the arrays
 *     alphabetically -- deterministic, so a re-save never churns key order
 *   - any object or array whose one-line form fits INLINE_THRESHOLD on one line
 *
 * Parses back to exactly the same value; only the layout differs.
 */

/**
 * Wide enough for a condition or a constraint -- the two objects a catalogue has thousands of --
 * to stay on one line (a condition is ~125 chars, a constraint with includeChildSelections
 * ~150). Measured on The Old World: 120 saved 13% of the lines, 160 saves 45%.
 */
export const INLINE_THRESHOLD = 160;

const FIRST = ["name", "id"];

function isScalar(v: unknown): boolean {
  return v === null || typeof v !== "object";
}

/** name, id, other scalars A-Z, then arrays/objects A-Z. */
function orderedEntries(obj: Record<string, unknown>): [string, unknown][] {
  const entries = Object.entries(obj).filter(([, v]) => v !== undefined);
  const rank = ([key, value]: [string, unknown]) => {
    const first = FIRST.indexOf(key);
    if (first >= 0) return first;
    return isScalar(value) ? FIRST.length : FIRST.length + 1;
  };
  return entries.sort((a, b) => rank(a) - rank(b) || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
}

function inline(value: unknown): string {
  if (isScalar(value)) return JSON.stringify(value) ?? "null";
  if (Array.isArray(value)) return `[${value.map(inline).join(", ")}]`;
  const parts = orderedEntries(value as Record<string, unknown>).map(([k, v]) => `${JSON.stringify(k)}: ${inline(v)}`);
  return parts.length ? `{${parts.join(", ")}}` : "{}";
}

function format(value: unknown, depth: number, indent: number): string {
  if (isScalar(value)) return JSON.stringify(value) ?? "null";
  const isArray = Array.isArray(value);
  const entries = isArray
    ? (value as unknown[]).map((v, i) => [String(i), v] as [string, unknown])
    : orderedEntries(value as Record<string, unknown>);
  if (!entries.length) return isArray ? "[]" : "{}";
  const oneLine = inline(value);
  if (oneLine.length <= INLINE_THRESHOLD) return oneLine;
  const pad = " ".repeat((depth + 1) * indent);
  const lines = entries.map(([key, val]) => {
    const inner = format(val, depth + 1, indent);
    return isArray ? `${pad}${inner}` : `${pad}${JSON.stringify(key)}: ${inner}`;
  });
  return `${isArray ? "[" : "{"}\n${lines.join(",\n")}\n${" ".repeat(depth * indent)}${isArray ? "]" : "}"}`;
}

export function compactStringify(value: unknown, indent = 2): string {
  return format(value, 0, indent);
}
